import {createCourseUI} from './course-ui.js';
import {canOpenTopic} from './learning.js';
import {topicId} from './course-content.js';
import {createAccounts,accountControls} from './accounts.js';
import {navigation} from './navigation.js';
import {createTutor} from './tutor-ui.js';
import {primaryStories,storyVisual} from './stories.js';
import {guides} from './guides.js';
import {ages,subjects,core,lessonFor} from './curriculum.js';
import {normalizeState,readState,complete,recordAttempt,mastery,result} from './engine.js';
let account=null;
const app=document.querySelector('#app');let state=readState(localStorage),page='home',sub='math',stage=0,step=0,val=4,mass=2,playing=false,hinted=false,focus=false,seconds=25*60,timer=null,filter='',dialog=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const age=()=>ages.find(a=>a.id===state.age)||ages[2],key=()=>state.age+':'+sub;
function save(){if(account?.save(state))return;try{localStorage.setItem('nexora-v1',JSON.stringify(state))}catch{toast('Storage is unavailable. Keep this tab open to preserve progress.')}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.className='show';clearTimeout(toast.t);toast.t=setTimeout(()=>t.className='',3500)}
const btn=(label,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${label}</button>`;
const logo=`<div class="brand"><span class="mark">N</span>NEXORA</div>`;
const navs=[['home','◫','Overview'],['subjects','◈','Explore subjects'],['projects','⌘','Projects'],['progress','▥','My progress'],['saved','◇','Saved lessons'],['settings','☷','Preferences']];
function art(){if(state.age==='primary')return `<svg class="orbit-art" viewBox="0 0 300 260" aria-hidden="true"><path d="M25 220q140-70 250 0" fill="#efd095"/><rect x="95" y="65" width="110" height="130" rx="40" fill="#2264e5"/><circle cx="128" cy="115" r="8" fill="white"/><circle cx="173" cy="115" r="8" fill="white"/><path d="M125 145q25 25 50 0" stroke="white" stroke-width="6" fill="none"/><path d="M80 130 45 90m170 40 35-40" stroke="#2264e5" stroke-width="17" stroke-linecap="round"/><path d="M245 42v26m-13-13h26M50 35v16m-8-8h16" stroke="#b47714" stroke-width="3"/></svg>`;return `<svg class="orbit-art" viewBox="0 0 300 260" aria-hidden="true"><defs><pattern id="grid" width="22" height="22" patternUnits="userSpaceOnUse"><path d="M22 0H0V22" fill="none" stroke="#ffffff0c"/></pattern></defs><rect width="300" height="260" fill="url(#grid)"/><g transform="translate(160 128)"><ellipse rx="105" ry="53" transform="rotate(-35)" fill="none" stroke="#42628f"/><ellipse rx="100" ry="70" transform="rotate(45)" fill="none" stroke="#42628f"/><path d="M0-61 53-30V31L0 62-53 31V-30Z" fill="#245bc7" stroke="#729bff" stroke-width="2"/><path d="M-53-30 0 0 53-30M0 0V62" fill="none" stroke="#a6c2ff" stroke-width="2"/><path d="M0-61V0" stroke="#517ff0"/><circle cx="-82" cy="45" r="13" fill="#f5b64c"/><circle cx="84" cy="-38" r="8" fill="#80a8ff"/><path d="M-72-70h12m-6-6v12M80 70h12m-6-6v12" stroke="#a8bfdf"/></g></svg>`}
function welcome(){app.innerHTML=`<div class="welcome"><header class="welcome-top">${logo}<div class="welcome-account">${accountControls(account?.user,account?.status)}</div></header><div class="onboard-intro"><span class="eyebrow" style="color:var(--blue)">A world of possibility starts here</span><h1>Big ideas.<br>A learning world that fits you.</h1><p class="muted">Six subjects. Four distinct experiences. Choose your age range and make your next discovery.</p></div><div class="age-grid">${ages.map(a=>`<button class="age-card" data-age="${a.id}"><div class="age-art">${a.icon}</div><div class="eyebrow">${a.range}</div><h3>${a.name}</h3><p>${a.desc}</p><span class="link">Let’s explore &nbsp; →</span></button>`).join('')}</div><p class="onboard-bottom">Start as a guest · No account needed · Change your age range anytime<br>Age shapes how you learn. Your understanding shapes your pace.</p></div>`}
function shell(content){const primary=state.age==='primary',middle=state.age==='middle';document.body.className=state.age+(state.reduced?' reduced':'')+(focus?' focus':'');app.innerHTML=`${navigation({age:state.age||'secondary',page,xp:state.xp,user:account?.user,status:account?.status})}${focus?`<div class="focus-toolbar"><span>Focus session · <b id="timer">${clock()}</b></span><div>${btn(timer?'Pause':'Resume','timer','small')}${btn('Exit focus','focus','small')}</div></div>`:''}${!primary&&!middle?`<aside class="sidebar"><div class="navlabel">YOUR LEARNING SPACE</div><nav aria-label="Workspace navigation">${navs.map(([p,i,l])=>`<button class="navbutton ${page===p?'active':''}" data-page="${p}" title="${l}"><span>${i}</span>${l}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><b>${age().name}</b><p style="margin:5px 0 10px">${age().range} · Your pace, your path.</p><button class="link" data-page="settings">Manage experience →</button></div></div></aside>`:''}<div class="main-shell"><main class="content" id="main">${content}</main></div>${dialog?onboardDialog():''}`}
function subjectCards(){const list=subjects.filter(s=>(s.name+' '+core[s.id].title).toLowerCase().includes(filter.toLowerCase()));return `<div class="subjects">${list.map(s=>`<button class="subject-card" data-subject="${s.id}"><span class="subject-icon ${s.color}">${s.icon}</span><h3>${s.short}</h3><p>${s.description}</p><div class="row card-footer"><span>${state.completed[state.age+':'+s.id]?'✓ Foundation completed':'Interactive learning path'}</span><span>→</span></div></button>`).join('')}</div>${!list.length?'<p class="empty">No matching lessons. Try “Science” or “repetition”.</p>':''}`}
function home(){const n=Object.entries(state.completed).filter(([k,v])=>k.startsWith(state.age+':')&&Date.now()-Date.parse(v.date)<7*86400000).length;const intro=state.age==='primary'?['Hello, explorer!','What will you discover today?']:state.age==='middle'?['Curiosity looks good on you.','Your next discovery is one experiment away.']:state.age==='advanced'?['Your learning, in focus.','Connect theory with practice. Build understanding that lasts.']:['Ready for your next breakthrough?','A little curiosity. A little progress. A world of possibilities.'];return `<div class="row greeting"><div><span class="eyebrow">${age().name} / YOUR SPACE TO GROW</span><h1>${intro[0]}</h1><p class="muted">${intro[1]}</p></div><span class="pill amber">✦ Level ${Math.floor(state.xp/200)+1}</span></div><div class="${state.age==='primary'?'':'dashboard-grid'}"><div><section class="hero"><div class="hero-copy"><span class="pill">${state.last?'PICK UP WHERE YOU LEFT OFF':'YOUR NEXT DISCOVERY'}</span><h2>${state.age==='primary'?'Little steps. Big discoveries.':state.age==='middle'?'What happens if you change one thing?':state.age==='advanced'?'From first principles to real possibilities.':'Build something.<br>Understand everything.'}</h2><p>${state.age==='primary'?'Join Pip for a story you can play.': 'Explore an idea, see it in action, and put your understanding to the test.'}</p>${btn(state.last?'Continue learning &nbsp; →':'Start exploring &nbsp; →','continue','amber')}</div>${art()}</section><div class="row section-head"><div><h2>${state.age==='primary'?'Choose your adventure':'Explore your subjects'}</h2><p>Six ways to see the world differently.</p></div><button class="link" data-page="subjects">View all →</button></div>${subjectCards()}<section class="project-banner row"><div><span class="eyebrow">THE NEXT STEP IS YOURS</span><h3 style="margin-top:8px">Small projects. Real understanding.</h3><p>Put an idea to work in a practical investigation.</p></div>${btn('Explore projects →','projects','secondary small')}</section></div>${state.age==='primary'?'':`<aside class="rightcol"><section class="panel"><div class="row"><h3>Your weekly goal</h3><span>◎</span></div><p class="micro">Make room for a little discovery.</p><div class="goal-ring" style="--progress:${Math.min(100,n/state.goal*100)}%"><div><strong>${Math.min(n,state.goal)} <span class="muted" style="font-size:15px">/ ${state.goal}</span></strong><small>LESSONS COMPLETED</small></div></div><div class="days">${['M','T','W','T','F','S','S'].map((d,i)=>`<span>${d}<i class="${state.visits.some(v=>(new Date(v).getDay()+6)%7===i)?'done':''}">${state.visits.some(v=>(new Date(v).getDay()+6)%7===i)?'✓':'·'}</i></span>`).join('')}</div><p class="micro" style="margin-top:17px;margin-bottom:0">Every step counts. Keep your own pace.</p></section><section class="panel"><h3>Your learning toolkit</h3><div class="mini-item"><span>◷</span><div><b>A little time to focus</b><p class="muted">Make space for one good idea.</p><button class="link" data-action="focus">Start a focus session →</button></div></div><div class="mini-item"><span>◇</span><div><b>Keep your discoveries</b><p class="muted">Save lessons to revisit later.</p><button class="link" data-page="saved">Open saved lessons →</button></div></div></section><section class="panel" style="background:#edf3ff;border-color:#dce8ff"><span class="eyebrow" style="color:var(--blue)">A LITTLE INSPIRATION</span><p style="font-size:13px;margin:12px 0 0">“The important thing is not to stop questioning.”</p><p class="micro" style="margin:8px 0 0">— Albert Einstein</p></section></aside>`}</div>`}
function onboardDialog(){return `<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-label="Choose your interests"><span class="eyebrow">MAKE IT YOURS · ${age().name}</span><h1>What sparks your curiosity?</h1><p class="muted">Choose your interests. All six subjects remain available.</p><div class="checks">${subjects.map(s=>`<label class="check"><input type="checkbox" name="interest" value="${s.id}" ${state.interests.includes(s.id)?'checked':''}> ${s.short}</label>`).join('')}</div><p class="micro">Begin with foundations, or take a short optional placement check. Your age never locks your knowledge level.</p><div class="row">${btn('Start with foundations →','finish-onboard')}${btn('Placement check','placement','secondary')}</div></section></div>`}
function overview(){const s=subjects.find(s=>s.id===sub),l=lessonFor(sub,state.age);return `<button class="link" data-page="subjects">← All subjects</button><div class="subject-heading"><span class="subject-icon ${s.color}">${s.icon}</span><span class="eyebrow">${age().name} / ${s.short}</span><h1>${s.name}</h1><p class="muted">${s.description}</p></div><section class="panel"><span class="pill blue">INTERACTIVE FOUNDATION</span><h2 style="margin-top:17px">${l.heading}</h2><p>${l.explanation}</p><div class="stack">${btn(state.completed[key()]?'Review lesson →':'Begin lesson →','lesson')}<span class="micro">${state.age==='primary'?'5':'12'} minute exploration · ${state.completed[key()]?'✓ Completed':'Available now'}</span></div></section><div class="section-head"><h2>Your subject map</h2><p>Each topic has guided instruction, a working model, practice, and a project notebook.</p></div><section class="panel">${s.topics.map((t,i)=>`<div class="topic-row"><span class="num">0${i+1}</span><div><h3>${t}</h3><p class="muted">${state.completed[topicId(state.age,sub,i,'apply')]?'✓ Mastered · review anytime':canOpenTopic(state,sub,i)?'Two learning stages · model · practice · project':'Locked · complete the previous topic'}</p></div><button class="btn secondary small" data-topic="${i}">${canOpenTopic(state,sub,i)?'Explore →':'See prerequisite'}</button></div>`).join('')}</section>`}
function visual(l){if(state.age==='primary')return storyVisual(sub,step,val,playing);let svg='',caption='';const blue='#2264e5',amber='#f5b64c';if(l.model==='fraction'){svg=`<g transform="translate(300 115)">${Array.from({length:8},(_,i)=>{const a=i*Math.PI/4,b=(i+1)*Math.PI/4;return `<path d="M0 0L${90*Math.cos(a)} ${90*Math.sin(a)}A90 90 0 0 1 ${90*Math.cos(b)} ${90*Math.sin(b)}Z" fill="${i<val?amber:'#fff'}" stroke="#142b4b" stroke-width="2"/>`}).join('')}</g><text x="440" y="125" font-size="30" fill="${blue}">${val}/8</text>`;caption=`${val} of 8 equal pieces are selected. ${val}/8 = ${val/8} of the whole.`}
if(l.model==='force'){svg=`<path d="M40 185H570" stroke="#9cabc0" stroke-width="3"/><g class="${playing?'moving':''}" style="--distance:${val*10}px"><rect x="110" y="95" width="120" height="65" rx="12" fill="${blue}"/><circle cx="135" cy="170" r="16" fill="#10233d"/><circle cx="205" cy="170" r="16" fill="#10233d"/><text x="170" y="135" fill="white" text-anchor="middle" font-size="22">${mass} kg</text><path d="M${245} 125h${val*15}l-12-8m12 8-12 8" stroke="${amber}" stroke-width="6" fill="none"/></g><text x="340" y="65" font-size="21" fill="${blue}">a = ${val} ÷ ${mass} = ${(val/mass).toFixed(2)} m/s²</text>`;caption=`Net force ${val} N on ${mass} kg gives acceleration ${(val/mass).toFixed(2)} m/s². This diagram illustrates the relationship; it is not a time-scaled trajectory.`}
if(l.model==='loop'){svg=Array.from({length:8},(_,i)=>`<rect x="${40+i*65}" y="110" width="52" height="52" rx="8" fill="${i<val?blue:'#fff'}" stroke="#9aacc6"/><text x="${66+i*65}" y="143" text-anchor="middle" fill="${i<val?'white':'#69758a'}" font-size="20">${i}</text>`).join('')+`<g class="${playing?'moving':''}"><rect x="${35+(Math.min(step,val-1))*65}" y="45" width="48" height="45" rx="15" fill="${amber}"/><circle cx="50" cy="65" r="3"/><circle cx="67" cy="65" r="3"/><path d="M50 76q8 7 16 0" fill="none" stroke="#10233d" stroke-width="2"/></g>`;caption=`Repeat ${val} times: counters ${result('loop',val).join(', ')}. The condition fails at ${val}, so the loop stops.`}
if(l.model==='network'){svg=`<path d="M70 120H530" stroke="#9eafc7" stroke-width="3" stroke-dasharray="7 5"/>${[70,220,370,530].map((x,i)=>`<rect x="${x-30}" y="90" width="60" height="60" rx="${i===0||i===3?5:30}" fill="${blue}"/><text x="${x}" y="127" text-anchor="middle" fill="white" font-size="20">${['▣','1','2','▣'][i]}</text><text x="${x}" y="185" text-anchor="middle" fill="#243957" font-size="13">${['Sender','Router','Router','Receiver'][i]}</text>`).join('')}<rect class="${playing?'moving':''}" x="110" y="110" width="20" height="20" fill="${amber}"/><text x="300" y="50" text-anchor="middle" fill="${blue}" font-size="22">3 links × ${val} ms = ${val*3} ms</text>`;caption=`The message crosses three links. At ${val} milliseconds per link, one-way delay is ${val*3} milliseconds in this simplified model.`}
if(l.model==='control'){svg=`<path d="M40 155H560" stroke="#9aadc7" stroke-width="3"/>${Array.from({length:11},(_,i)=>`<text x="${50+i*49}" y="183" text-anchor="middle" font-size="14">${i}</text>`).join('')}<path d="M${50+val*49} 45v110m0-110h35l-12 15 12 15h-35" fill="${amber}" stroke="#b57817"/><rect x="${50+result('control',val)*49-22}" y="115" width="44" height="32" rx="8" fill="${blue}"/><text x="300" y="215" text-anchor="middle" font-size="17" fill="${blue}">2 + 0.5 × (${val} − 2) = ${result('control',val)}</text>`;caption=`Starting position 2. Target ${val}. Error ${val-2}. With gain 0.5, one correction reaches ${result('control',val)}. Repeat measurement and correction to approach the target.`}
if(l.model==='data'){const mean=result('data',val);svg=`<path d="M100 20v180h410" fill="none" stroke="#9aacc5"/>${[2,4,val].map((v,i)=>`<rect x="${150+i*120}" y="${200-v*15}" width="65" height="${v*15}" fill="${i===2?amber:blue}"/><text x="${182+i*120}" y="225" text-anchor="middle" font-size="19">${v}</text>`).join('')}<path d="M100 ${200-mean*15}H510" stroke="#152e52" stroke-width="2" stroke-dasharray="6 4"/><text x="515" y="${203-mean*15}" font-size="14">mean</text>`;caption=`Values: 2, 4, ${val}. Total ${6+val}. Mean ${(mean).toFixed(2)}. The dashed line marks the equal share.`}
return `<div class="visual ${playing?'animate':''}" role="figure" aria-label="${esc(caption)}"><svg viewBox="0 0 600 250" aria-hidden="true">${svg}</svg><p class="visual-caption" id="caption">${caption}</p></div>`}
function simulation(l){if(state.age==='primary')return `${visual(l)}<div class="controls">${btn('◀ Previous picture','previous-step','secondary')}${btn('Next picture →','step')}</div><p>${l.activity}</p>`;const labels={fraction:'Selected pieces',force:'Net force (N)',loop:'Repeat count',network:'Delay per link (ms)',control:'Target position',data:'Third value'};return `${visual(l)}<div class="controls"><label>${labels[l.model]} <input id="variable" type="range" min="1" max="${l.model==='data'?12:l.model==='control'?10:8}" value="${val}"><output>${val}</output></label>${l.model==='force'?`<label>Mass <select id="mass">${[1,2,4].map(n=>`<option ${n===mass?'selected':''}>${n}</option>`).join('')}</select> kg</label>`:''}${btn(playing?'Pause demo':'Play demo','play','secondary small')}${btn('Next step','step','secondary small')}</div><p class="micro">${l.activity} ${state.reduced?'Reduced motion is on. Use Next step for a still-frame explanation.':''}</p>`}
function audio(){return `<div class="audio" aria-label="Read aloud controls"><button data-action="speak">◖ Read aloud</button><button data-action="pause-audio">Pause / resume</button><button data-action="stop-audio">Stop</button><label>Speed <select id="speech-rate"><option value="0.8">0.8×</option><option value="1" selected>1×</option><option value="1.2">1.2×</option></select></label></div>`}
function lesson(){const l=lessonFor(sub,state.age),primary=state.age==='primary';const names=primary?['Watch the story','Try it yourself','Show what you know']:state.age==='middle'?['Discover','Experiment','Mission check']:state.age==='advanced'?['Theory & model','Investigation','Evaluate & reflect']:['Understand','Build & debug','Apply your knowledge'];return `<div class="row"><button class="link" data-action="overview">← ${subjects.find(s=>s.id===sub).short}</button><div class="stack"><button class="bookmark ${state.bookmarks.includes(key())?'active':''}" data-action="bookmark" aria-label="Save lesson">◇ ${state.bookmarks.includes(key())?'Saved':'Save'}</button><button class="link" data-action="focus">${focus?'Exit focus':'◷ Focus'}</button></div></div><div class="lesson-layout" style="margin-top:25px">${primary?'':`<aside class="lesson-nav"><h3>${state.age==='advanced'?'Research outline':'Your learning path'}</h3>${names.map((n,i)=>`<button data-stage="${i}" class="${stage===i?'current':''}" ${i>stage?'disabled':''}>${i<stage?'✓':String(i+1).padStart(2,'0')} &nbsp; ${n}</button>`).join('')}<p class="micro">${l.objective}</p></aside>`}<article class="lesson-body"><span class="eyebrow">${subjects.find(s=>s.id===sub).short} / ${names[stage]}</span><h1>${l.heading}</h1>${audio()}${stage===0?`${primary?'':`<p>${l.explanation}</p><p class="micro"><b>Before you begin:</b> ${l.prereq}</p>`}${visual(l)}<div class="step-card"><span class="step-number">${step+1}</span><span id="step-text">${primary?primaryStories[sub][step]:l.steps[step]}</span></div><div class="controls">${btn(playing?'Pause story':'▶ '+(primary?'Watch the story':'Animate concept'),'play','secondary')}${btn('Next step →','step','secondary')}</div>${primary?`<p>${l.explanation}</p>`:`<details><summary>Two worked examples</summary>${l.examples.map((e,i)=>`<p><b>Example ${i+1}.</b> ${e}</p>`).join('')}</details>`}`:stage===1?`${simulation(l)}${sub==='coding'&&state.age!=='primary'?`<h3>JavaScript workspace</h3><p class="micro">Code runs in an isolated worker with a one-second limit. Use console.log to inspect values.</p><textarea class="code-editor" id="code" aria-label="JavaScript editor" spellcheck="false">${esc(state.age==='advanced'?'let sum = 0;\nfor (let i = 1; i <= 5; i++) {\n  sum += i;\n}\nconsole.log(sum);':'for (let i = 0; i < 4; i++) {\n  console.log(i);\n}')}</textarea>${btn('Run code ▷','run','small')}<pre id="code-output" class="output" role="status">Output appears here.</pre>`:''}<section class="step-card"><h3>${primary?'Something to notice':'Check your assumptions'}</h3><p>${l.mistake}</p></section>${!primary?`<h3>Apply it</h3><p>${l.project}</p><label for="notes">Your investigation notes</label><textarea id="notes" class="notes" placeholder="Prediction, observation, explanation…">${esc(state.notes[key()]||'')}</textarea>`:''}`:`<section class="panel"><span class="pill blue">${state.completed[key()]?'REVISION':'UNDERSTANDING CHECK'}</span><p class="question">${l.question}</p><form id="answer-form"><label for="answer">Your answer ${sub==='science'?'(use the units in the question)':''}</label><div class="stack" style="margin-top:12px"><input class="answer-input" id="answer" type="number" step="any" required autocomplete="off"><button class="btn" type="submit">Check answer →</button></div></form><button class="link" style="margin-top:20px" data-action="hint">Give me a hint</button><div id="feedback" aria-live="polite"></div></section><section class="step-card"><h3>Take it with you</h3><p>${l.objective}</p><p>${l.mistake}</p></section>`}<div class="lesson-actions">${stage?btn('← Back','back-stage','secondary'):'<span></span>'}${stage<2?btn(primary?['Let me try →','I’m ready →'][stage]:['Explore the model →','Check understanding →'][stage],'next-stage'):btn('Explore another subject →','subjects','secondary')}</div></article></div>`}
function progress(){const n=Object.keys(state.completed).length;return `<span class="eyebrow">YOUR LEARNING, MADE VISIBLE</span><h1>${state.age==='primary'?'Look how far you’ve come!':'Small steps. Measurable progress.'}</h1><p class="muted">Evidence from practice in your current age experience. ${account?.user?esc(account.status):'Saved on this device.'}</p><div class="stats"><div class="panel stat"><strong>${n}</strong><small>Completed lessons</small></div><div class="panel stat"><strong>${state.xp}</strong><small>Experience points</small></div><div class="panel stat"><strong>${state.visits.length}</strong><small>Days of discovery</small></div></div><section class="panel"><h2>Subject mastery</h2><table class="table"><thead><tr><th>Subject</th><th>Evidence</th><th>Topic path</th><th>Recommendation</th></tr></thead><tbody>${subjects.map(s=>{const m=mastery(state,s.id);return `<tr><td>${s.short}</td><td>${m}%<div class="progressbar"><div style="width:${m}%"></div></div></td><td>${Array.from({length:6},(_,i)=>state.completed[topicId(state.age,s.id,i,'apply')]).filter(Boolean).length}/6 topics</td><td>${m>=80?'Extend with a project':m?'Revisit the worked examples':'Start the foundation'}</td></tr>`}).join('')}</tbody></table><p class="micro">An initial estimate from practice accuracy and hint use. One lesson does not establish mastery of an entire subject.</p></section><div class="section-head"><h2>Milestones</h2></div><div class="two-col"><section class="panel"><span class="badge">✦</span><h3>First discovery</h3><p>${n?'Earned — you completed your first understanding check.':'Complete a lesson to earn your first milestone.'}</p></section><section class="panel"><span class="badge">◈</span><h3>Across disciplines</h3><p>${new Set(Object.keys(state.completed).map(k=>k.split(':')[1])).size===6?'Earned — six subjects, six new perspectives.':'Complete one lesson in each of the six subjects.'}</p></section></div>`}
function settings(){return `<button class="link settings-back" data-page="home">← Back to dashboard</button><br><br><span class="eyebrow">MAKE NEXORA YOURS</span><h1>Learning preferences</h1><div class="two-col"><section class="panel"><h2>Your experience</h2><p class="muted">Change how concepts are taught. Progress in each experience is kept separately.</p><label for="age-setting">Age range</label><select id="age-setting" style="display:block;width:100%;padding:12px;margin:12px 0">${ages.map(a=>`<option value="${a.id}" ${a.id===state.age?'selected':''}>${a.range} — ${a.name}</option>`).join('')}</select><label><input id="reduce" type="checkbox" ${state.reduced?'checked':''}> Use still frames instead of animation</label><p class="micro">Your device’s reduced-motion preference is also respected.</p><label class="duration-setting">Study session (minutes) <input id="focus-minutes" class="answer-input" type="number" min="5" max="90" value="${state.focus.minutes}"></label><label class="duration-setting">Break reminder (minutes) <input id="break-minutes" class="answer-input" type="number" min="1" max="30" value="${state.focus.breakMinutes}"></label><p class="micro">${state.focus.sessions.length} completed focus sessions. Focus mode only reduces distractions inside NEXORA; it cannot block other apps or websites.</p><label class="duration-setting">Weekly lesson goal <input id="goal" type="number" min="1" max="12" value="${state.goal}" class="answer-input"></label></section><section class="panel"><h2>Progress & storage</h2><span class="pill blue">${account?.user?'Your account':'Guest · This device'}</span><p data-sync-status>${esc(account?.status||'Saved in this browser')}</p><p>${account?.user?'Your progress is kept separately for this account. Pending changes stay in an account-specific local copy until synchronization succeeds.':'Explore as a guest, or create an account to synchronize progress once Supabase is configured. Export a backup before clearing browser data.'}</p>${account?.user?'<button class="link" data-account="sync">Sync now</button>':'<button class="link" data-page="signup">Create an account →</button>'}${btn('Export progress','export','secondary')}<label class="btn secondary" style="margin-top:10px">Import backup<input type="file" id="import" accept="application/json" hidden></label><p class="micro" id="storage-status">${navigator.onLine?'You’re online.':'You’re offline. Saved learning continues on this device.'}</p></section></div>`}
function projects(){return `<span class="eyebrow">PUT YOUR IDEAS TO WORK</span><h1>${state.age==='primary'?'Make a little discovery':'The project bench'}</h1><p class="muted">Six practical investigations. No special hardware required.</p><div class="two-col">${subjects.map(s=>`<section class="panel"><span class="subject-icon ${s.color}">${s.icon}</span><h3>${core[s.id].title}</h3><p>${core[s.id].project}</p><button class="btn secondary" data-project="${s.id}">${state.completed[state.age+':'+s.id]?'Open investigation →':'Learn the foundation first →'}</button></section>`).join('')}</div>`}
function render(){if(['signup','login','profile','recover','reset'].includes(page)){shell(account.view(page));return}if(!state.age){welcome();return}let c=page==='home'?home():page==='subjects'?`<span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h1>Six subjects. Endless connections.</h1><p class="muted">${age().verb}</p><label class="browse-search">Search subjects and lessons <input id="search" class="search" placeholder="Search by subject or concept…" value="${esc(filter)}"></label>${subjectCards()}`:page==='overview'?overview():page==='lesson'?lesson():page==='progress'?progress():page==='settings'?settings():page==='projects'?projects():page==='saved'?`<h1>Your saved discoveries</h1>${state.bookmarks.length?state.bookmarks.map(k=>`<section class="panel" style="margin-bottom:12px"><div class="row"><div><span class="eyebrow">${ages.find(a=>a.id===k.split(':')[0]).name}</span><h3>${lessonFor(k.split(':')[1],k.split(':')[0]).heading}</h3></div><button class="btn secondary" data-saved="${k}">Revisit →</button></div></section>`).join(''):'<div class="empty">Save a lesson with the ◇ button to return to it here.</div>'}`:page==='topic'?topicView():page==='placement'?placement():home();shell(c)}
function go(p){course.stop();if(['signup','login','profile','recover','reset'].includes(p))account?.clearMessages();page=p;playing=false;clearInterval(playTimer);window.speechSynthesis?.cancel?.();render();window.scrollTo(0,0)}
let playTimer=null;function startLesson(){state.last=sub;state.lastTopic=null;save();stage=0;step=0;val=4;hinted=false;go('lesson')}
function clock(){return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function toggleTimer(){if(!seconds)seconds=state.focus.minutes*60;if(timer){clearInterval(timer);timer=null}else timer=setInterval(()=>{if(seconds>0)seconds--;const el=document.querySelector('#timer');if(el)el.textContent=clock();if(!seconds){clearInterval(timer);timer=null;state.focus.sessions.push({date:new Date().toISOString(),minutes:state.focus.minutes});state.focus.sessions=state.focus.sessions.slice(-100);save();toast('Session complete. Take a '+state.focus.breakMinutes+'-minute break.');render()}},1000)}
function speak(){if(!('speechSynthesis'in window)){toast('Read aloud is unavailable in this browser. All narration is shown as text.');return}speechSynthesis.cancel();const text=document.querySelector('.lesson-body')?.innerText||document.querySelector('main')?.innerText;const u=new SpeechSynthesisUtterance(text);u.rate=Number(document.querySelector('#speech-rate')?.value||1);u.onerror=()=>toast('Audio could not play. The full explanation is available on screen.');speechSynthesis.speak(u)}
function runCode(){const source=document.querySelector('#code').value,out=document.querySelector('#code-output');out.textContent='Running…';const blob=new Blob([`self.fetch=undefined;self.XMLHttpRequest=undefined;self.WebSocket=undefined;self.importScripts=undefined;self.console={log:(...a)=>postMessage({log:a.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(' ')})};onmessage=async e=>{try{new Function(e.data)();postMessage({done:true})}catch(e){postMessage({error:e.message})}}`],{type:'text/javascript'});const url=URL.createObjectURL(blob),worker=new Worker(url);let logs=[],done=false;const stop=()=>{worker.terminate();URL.revokeObjectURL(url);done=true};const deadline=setTimeout(()=>{if(!done){stop();out.textContent=logs.join('\n')+'\nStopped: one-second execution limit.'}},1000);worker.onmessage=e=>{if(e.data.log!==undefined){if(logs.length<100)logs.push(e.data.log);else{stop();out.textContent='Stopped: output limit reached.'}}if(e.data.done||e.data.error){clearTimeout(deadline);stop();out.textContent=e.data.error?'Error: '+e.data.error:logs.join('\n')||'(No console output)'}};worker.onerror=e=>{stop();out.textContent='Execution error: '+e.message};worker.postMessage(source)}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.age){state.age=b.dataset.age;dialog=true;render();return}if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.subject){sub=b.dataset.subject;go('overview');return}if(b.dataset.stage){stage=Number(b.dataset.stage);render();return}if(b.dataset.topic!==undefined){topicIndex=Number(b.dataset.topic);if(canOpenTopic(state,sub,topicIndex)){state.last=sub;state.lastTopic={age:state.age,subject:sub,index:topicIndex};save()}go('topic');return}if(b.dataset.project){sub=b.dataset.project;startLesson();if(state.completed[key()]){stage=1;render()}return}if(b.dataset.saved){[state.age,sub]=b.dataset.saved.split(':');save();startLesson();return}const a=b.dataset.action;if(a==='finish-onboard'||a==='placement'){state.interests=[...document.querySelectorAll('[name=interest]:checked')].map(c=>c.value);dialog=false;save();go(a==='placement'?'placement':'home')}else if(a==='continue'){if(state.lastTopic?.age===state.age){sub=state.lastTopic.subject;topicIndex=state.lastTopic.index;go('topic')}else{sub=state.last||state.interests[0]||'coding';startLesson()}}else if(['subjects','projects','overview'].includes(a))go(a);else if(a==='lesson')startLesson();else if(a==='next-stage'){stage=Math.min(2,stage+1);playing=false;clearInterval(playTimer);render()}else if(a==='back-stage'){stage=Math.max(0,stage-1);render()}else if(a==='previous-step'){step=(step+3)%4;render()}else if(a==='step'){step=(step+1)%4;val=step===0?1:step===1?2:step===2?4:6;render()}else if(a==='play'){if(state.reduced||window.matchMedia('(prefers-reduced-motion: reduce)').matches){step=(step+1)%4;render();toast('Still-frame mode: use Next step to continue.');return}playing=!playing;clearInterval(playTimer);if(playing){playTimer=setInterval(()=>{step=(step+1)%4;val=[1,2,4,6][step];render()},1800)}render()}else if(a==='bookmark'){state.bookmarks=state.bookmarks.includes(key())?state.bookmarks.filter(k=>k!==key()):[...state.bookmarks,key()];save();render()}else if(a==='hint'){hinted=true;document.querySelector('#feedback').innerHTML=`<div class="feedback">${lessonFor(sub,state.age).hint}</div>`}else if(a==='speak')speak();else if(a==='pause-audio'){if('speechSynthesis'in window){speechSynthesis.paused?speechSynthesis.resume():speechSynthesis.pause()}}else if(a==='stop-audio')window.speechSynthesis?.cancel();else if(a==='run')runCode();else if(a==='focus'){focus=!focus;if(focus&&!timer){seconds=state.focus.minutes*60;toggleTimer();}if(!focus&&timer)toggleTimer();render()}else if(a==='timer'){toggleTimer();render()}else if(a==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download='nexora-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}else if(a==='placement-submit'){const v=Number(document.querySelector('#placement-answer').value);state.level.math=v===6?'extension':'foundation';save();toast(v===6?'Start with the fraction investigation.':'Start with the visual fraction foundation.');sub='math';startLesson();if(v===6){stage=1;render()}}});
app.addEventListener('input',e=>{if(e.target.id==='search'){filter=e.target.value;page='subjects';const sel=e.target.selectionStart;render();const s=document.querySelector('#search');s.focus();s.setSelectionRange(sel,sel)}if(e.target.id==='variable'){val=Number(e.target.value);const l=lessonFor(sub,state.age);document.querySelector('.visual').outerHTML=visual(l);e.target.nextElementSibling.textContent=val}if(e.target.id==='guide-note'){state.notes[key()+':guide:'+topicIndex]=e.target.value;save()}if(e.target.id==='notes'){state.notes[key()]=e.target.value;save()}});
app.addEventListener('change',async e=>{if(e.target.id==='focus-minutes'){state.focus.minutes=Math.max(5,Math.min(90,Number(e.target.value)||25));save()}if(e.target.id==='break-minutes'){state.focus.breakMinutes=Math.max(1,Math.min(30,Number(e.target.value)||5));save()}if(e.target.id==='age-setting'){state.age=e.target.value;save();render()}if(e.target.id==='reduce'){state.reduced=e.target.checked;save();render()}if(e.target.id==='goal'){state.goal=Math.max(1,Math.min(12,Number(e.target.value)||3));save();render()}if(e.target.id==='mass'){mass=Number(e.target.value);render()}if(e.target.id==='import'){try{const data=JSON.parse(await e.target.files[0].text());if(data.version!==1||!ages.some(a=>a.id===data.age)||typeof data.completed!=='object'||!Array.isArray(data.bookmarks))throw Error();state=normalizeState(data);save();render();toast('Backup restored.')}catch{toast('This file is not a valid NEXORA progress backup.')}}});
app.addEventListener('submit',e=>{if(e.target.id!=='answer-form')return;e.preventDefault();const l=lessonFor(sub,state.age),answer=Number(document.querySelector('#answer').value),correct=Math.abs(answer-l.answer)<0.001,a=recordAttempt(state,key(),correct,hinted);if(correct){const awarded=complete(state,key(),hinted);document.querySelector('#feedback').innerHTML=`<div class="feedback"><b>✓ You’ve got it.</b><p>${l.hint} The result is ${l.answer}.</p><p>${awarded?`Lesson complete · +${hinted?30:50} XP`:'Revision recorded. Your completion reward was already earned.'}</p><button class="btn small" data-page="projects">Try a project →</button></div>`}else{document.querySelector('#feedback').innerHTML=`<div class="feedback"><b>Let’s work through it.</b><p>${a.tries>1?l.hint:'Revisit the model and check what each number represents. You can try again.'}</p></div>`}save()});
let topicIndex=0;
function placement(){return `<section class="panel" style="max-width:700px;margin:auto"><span class="eyebrow">OPTIONAL STARTING-POINT CHECK</span><h1>Find your starting point</h1><p>This short mathematics check recommends a starting point. It does not determine your ability in other subjects.</p><p class="question">How many eighths represent three quarters?</p><label>Your answer <input id="placement-answer" type="number" class="answer-input"></label><div class="controls">${btn('Get my recommendation','placement-submit')}${btn('Skip and explore','subjects','secondary')}</div></section>`}
function topicView(){return course.view()}
const course=createCourseUI({getState:()=>state,getSubject:()=>sub,getIndex:()=>topicIndex,save,render,notify:toast,runCode});
const tutor=createTutor(()=>({age:state.age,subject:['lesson','overview','topic'].includes(page)?sub:null,contextType:page==='topic'?'course':page==='lesson'?'foundation':'general',topic:page==='topic'?topicIndex:null,mastery:mastery(state,sub),label:page==='lesson'?lessonFor(sub,state.age).heading:page==='topic'?guides[sub][topicIndex][0]:'All six subjects'}));
app.addEventListener('click',e=>{if(e.target.closest('[data-tutor-open]')){playing=false;clearInterval(playTimer);tutor.open()}});
account=createAccounts({getState:()=>state,onState:(next,rerender=true)=>{state=normalizeState(next);if(rerender)render()},onChange:()=>render(),notify:toast,navigate:go,resetPrivateUI:()=>{tutor.reset();course.stop();clearInterval(playTimer);playing=false;clearInterval(timer);timer=null;focus=false;window.speechSynthesis?.cancel()}});
const today=new Date().toISOString().slice(0,10);if(!state.visits.includes(today)){state.visits.push(today);save()}render();account.init();

const accountReturn=new URLSearchParams(location.search);if(accountReturn.has('auth_error'))toast('Confirmation failed or expired. Try logging in if your email is already confirmed.');if(accountReturn.has('confirmed'))toast('Email confirmed. Loading your account…');if(accountReturn.has('auth_error')||accountReturn.has('confirmed'))history.replaceState(null,'',location.pathname);

if(accountReturn.has('password_reset')){page='reset';render();history.replaceState(null,'',location.pathname);}
